def compute(vars):
    shares_outstanding_2012 = vars["v1"]
    acquisition_shares = vars["v2"]
    result = shares_outstanding_2012 - acquisition_shares

    return {
        "value": result,
        "trace": {
            "shares_outstanding_2012": shares_outstanding_2012,
            "acquisition_shares": acquisition_shares,
            "result": result,
            "output_meta": {
                "currency": None,
                "scale": "million",
                "unit": "shares"
            }
        }
    }
